    ///     Removes Template from `browseTemplates`.
    ///     <a target="_blank" href="https://developers.arcgis.com/javascript/latest/api-reference/esri-widgets-Print-PrintViewModel.html#removePortalTemplate">ArcGIS Maps SDK for JavaScript</a>
    /// </summary>
    /// <param name="template">
    ///     The <a target="_blank" href="https://developers.arcgis.com/javascript/latest/api-reference/esri-widgets-Print-CustomTemplate.html">CustomTemplate</a> will be removed.
    /// </param>
    [ArcGISMethod]
    public async Task RemovePortalTemplate(CustomTemplate template)
    {
        if (CoreJsModule is null)
        {
            return;
        }
        
        try 
        {
            JsComponentReference ??= await CoreJsModule.InvokeAsync<IJSObjectReference?>(
                "getJsComponent", CancellationTokenSource.Token, Id);
        }
        catch (JSException)
        {
            // this is expected if the component is not yet built
        }
        
        if (JsComponentReference is null)
        {
            return;
        }
        
        await JsComponentReference!.InvokeVoidAsync(
            "removePortalTemplate", 
            CancellationTokenSource.Token,
            template);
    }
    
    /// <summary>
    ///     <a target="_blank" href="https://docs.geoblazor.com/pages/classes/dymaptic.GeoBlazor.Pro.Components.PrintViewModel.html#printviewmodeltoprinttemplate-method">GeoBlazor Docs</a>
    ///     Helper method to create print templates from a template options object.
    /// </summary>
    /// <param name="templateOptions">
    ///     <a target="_blank" href="https://developers.arcgis.com/javascript/latest/api-reference/esri-widgets-Print-PrintViewModel.html#toPrintTemplate">ArcGIS Maps SDK for JavaScript</a>
    /// </param>
    [ArcGISMethod]
    public async Task<PrintTemplate?> ToPrintTemplate(TemplateOptions templateOptions)
    {
        if (CoreJsModule is null)
        {
            return null;
        }
        
        try
        {
            JsComponentReference ??= await CoreJsModule.InvokeAsync<IJSObjectReference?>(
                "getJsComponent", CancellationTokenSource.Token, Id);
        }
        catch (JSException)
        {
            // this is expected if the component is not yet built
        }
        
        if (JsComponentReference is null)
        {
            return null;
        }
        
        return await JsComponentReference!.InvokeAsync<PrintTemplate?>(
            "toPrintTemplate", 
            CancellationTokenSource.Token,
            templateOptions);
    }
    
#endregion


    /// <inheritdoc />
    protected override async ValueTask<bool> RegisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case SpatialReference outSpatialReference:
                if (outSpatialReference != OutSpatialReference)
                {
                    OutSpatialReference = outSpatialReference;
                    ModifiedParameters[nameof(OutSpatialReference)] = OutSpatialReference;
                }
                
                return true;
            case Portal portal:
                if (portal != Portal)
                {
                    Portal = portal;
                    ModifiedParameters[nameof(Portal)] = Portal;
                }
                
                return true;
            default:
                return await base.RegisterGeneratedChildComponent(child);
        }
    }

    /// <inheritdoc />
    protected override async ValueTask<bool> UnregisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case SpatialReference _:
                OutSpatialReference = null;
                ModifiedParameters[nameof(OutSpatialReference)] = OutSpatialReference;
                return true;
            case Portal _:
                Portal = null;
                ModifiedParameters[nameof(Portal)] = Portal;
                return true;
            default:
                return await base.UnregisterGeneratedChildComponent(child);
        }
    }
    
    /// <inheritdoc />
    public override void ValidateRequiredGeneratedChildren()
    {
    
        OutSpatialReference?.ValidateRequiredGeneratedChildren();
        Portal?.ValidateRequiredGeneratedChildren();
        base.ValidateRequiredGeneratedChildren();
    }
      
}
